custom_css:
/* 功能、焦点与动效保护。 */

body {
    color: var(--ld-ink);
    background-color: var(--ld-navy);
    font-family: var(--ld-font-body);
    font-synthesis: none;
    text-shadow: none;
}

#bg1,
#bg_custom {
    background-color: var(--ld-navy);
    background-image: var(--ld-background-image);
    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;
}

:is(
    #top-settings-holder,
    #chat,
    #send_form,
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup,
    #options,
    #extensionsMenu
) :is(button, input, textarea, select, [tabindex]):focus-visible {
    outline: 2px solid var(--ld-peach);
    outline-offset: 2px;
}

#chat .mes::before,
#chat .mes::after,
#top-settings-holder .drawer-toggle::after,
#send_form::before,
#send_form::after,
#options_button::after,
#extensionsMenuButton::after,
#send_but::after {
    pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
    :is(#chat, #top-bar, #send_form, .drawer-content, .popup, #options, #extensionsMenu) {
        scroll-behavior: auto;
        transition-duration: 0.01ms;
        animation-duration: 0.01ms;
        animation-iteration-count: 1;
    }
}

/*
 * 蓝蝶 · 设计令牌
 * Author: @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 */

@font-face {
    font-family: "Source Han Serif SC BlueButterfly";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/sourcehanserifsc/sourcehanserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Cormorant SC BlueButterfly";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/cormorant-sc/CormorantSC-Regular.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --ld-navy: #0e2d43;
    --ld-blue: #1f5285;
    --ld-mist: #84a9b8;
    --ld-pearl: #a4aaaa;
    --ld-peach: #f8c5a2;
    --ld-ink: #c5cbca;
    --ld-muted: #879aa0;
    --ld-text-cool: #789aa8;
    --ld-text-warm: #d39f84;
    --ld-deep: #081d2c;
    --ld-panel: rgba(14, 45, 67, 0.96);
    --ld-panel-soft: rgba(31, 82, 133, 0.78);
    --ld-message: rgba(14, 45, 67, 0.92);
    --ld-message-user: rgba(31, 82, 133, 0.88);
    --ld-line: rgba(132, 169, 184, 0.46);
    --ld-line-soft: rgba(132, 169, 184, 0.25);
    --ld-focus: rgba(248, 197, 162, 0.82);
    --ld-success: #9ccbb7;
    --ld-warning: #f8c5a2;
    --ld-error: #e59898;
    --ld-radius-xs: 6px;
    --ld-radius-sm: 12px;
    --ld-radius-md: 22px;
    --ld-radius-wing: 6px 22px 6px 22px;
    --ld-shadow: 0 18px 42px rgba(2, 17, 29, 0.38);
    --ld-shadow-soft: 0 8px 24px rgba(2, 17, 29, 0.28);
    --ld-font-body: "Source Han Serif SC BlueButterfly", "Source Han Serif SC", "Noto Serif SC", serif;
    --ld-font-display: "Cormorant SC BlueButterfly", "Cormorant SC", "Source Han Serif SC BlueButterfly", serif;
    --ld-font-mono: "Courier Prime", "Cascadia Mono", Consolas, monospace;
    --ld-background-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/9c173d4d0e6fb64a5b3c9babb2ffb1a34c41939b/assets/%E8%93%9D%E8%9D%B6/blue-butterfly-dream-background.png");
    --ld-avatar-user-ornament-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/ab973081543e77ebbbf3ecdc24e341ae0e8f55e1/assets/%E8%93%9D%E8%9D%B6/avatar-user-butterfly-comet.png");
    --ld-avatar-character-ornament-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/ab973081543e77ebbbf3ecdc24e341ae0e8f55e1/assets/%E8%93%9D%E8%9D%B6/avatar-character-star-garden.png");
    --ld-slider-butterfly-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/683882cab67569571cb1c1135d621193867f0bb1/assets/%E8%93%9D%E8%9D%B6/slider-butterfly-thumb.png");
    --ld-speed: 160ms;
}

/* W01 · 顶部居中头像编辑排版。沿用原生消息 Flex，仅改为纵向主轴。 */

#chat {
    color: var(--ld-ink);
    border-inline: 1px solid var(--ld-line-soft);
    background-color: rgba(8, 29, 44, 0.90);
    box-shadow: inset 0 0 60px rgba(31, 82, 133, 0.20), var(--ld-shadow);
    text-shadow: none;
}

#chat .mes:not([is_system="true"]) {
    position: relative;
    flex-direction: column;
    align-items: stretch;
    box-sizing: border-box;
    margin-block: 14px;
    padding: 18px 22px;
    color: var(--ld-ink);
    border: 0;
    border-radius: 0;
    background-color: transparent;
    background-image: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes:not([is_system="true"])::before,
#chat .mes:not([is_system="true"])::after {
    position: absolute;
    z-index: 1;
    color: var(--ld-mist);
    font-family: var(--ld-font-display);
    line-height: 1;
    text-shadow: 0 0 12px currentColor;
}

#chat .mes:not([is_system="true"])::before {
    content: "✦";
    top: 9px;
    left: 11px;
    font-size: 14px;
}

#chat .mes:not([is_system="true"])::after {
    content: "✧";
    right: 13px;
    bottom: 10px;
    color: var(--ld-peach);
    font-size: 20px;
}

#chat .mes[is_user="true"]::before {
    right: 12px;
    left: auto;
    color: var(--ld-peach);
}

#chat .mes[is_user="true"]::after {
    right: auto;
    left: 13px;
    color: var(--ld-mist);
}

#chat .mes > .mes_block {
    box-sizing: border-box;
    flex: 1 1 auto;
    align-self: stretch;
    width: 100%;
    min-width: 0;
    margin: 0;
    padding-inline: 10px;
}

#chat .mes:not([is_system="true"]) > .mesAvatarWrapper {
    position: relative;
    flex: 0 0 auto;
    align-self: center;
    width: auto;
    min-width: 0;
    height: auto;
    min-height: 0;
    margin: 0 auto 13px;
    padding: 0;
}

#chat .last_mes:not([is_system="true"]) > .mesAvatarWrapper {
    padding-bottom: 0;
}

#chat .mes:not([is_system="true"]) > .mesAvatarWrapper::before {
    content: "";
    position: absolute;
    z-index: 0;
    top: 50%;
    left: 50%;
    width: 460px;
    height: 190px;
    background-position: center;
    background-repeat: no-repeat;
    background-size: contain;
    opacity: 0.94;
    pointer-events: none;
    transform: translate(-50%, -50%);
}

#chat .mes[is_user="true"] > .mesAvatarWrapper::before {
    background-image: var(--ld-avatar-user-ornament-image, none);
}

#chat .mes[is_user="false"] > .mesAvatarWrapper::before {
    background-image: var(--ld-avatar-character-ornament-image, none);
}

#chat .mes:not([is_system="true"]) > .mesAvatarWrapper .avatar {
    position: relative;
    z-index: 1;
    box-sizing: border-box;
    flex: 0 0 auto;
    width: 76px;
    height: 76px;
    padding: 3px;
    border: 1px solid var(--ld-mist);
    border-radius: 50%;
    background-color: var(--ld-navy);
    box-shadow: 0 0 0 4px rgba(14, 45, 67, 0.94), 0 10px 24px rgba(2, 17, 29, 0.34);
}

#chat .mes[is_user="true"] > .mesAvatarWrapper .avatar {
    border-color: var(--ld-peach);
    box-shadow: 0 0 0 4px rgba(31, 82, 133, 0.94), 0 10px 24px rgba(2, 17, 29, 0.34);
}

#chat .mes:not([is_system="true"]) > .mesAvatarWrapper .avatar img {
    width: 100%;
    height: 100%;
    border-radius: inherit;
    object-fit: cover;
    object-position: center;
}

#chat .mes .ch_name {
    justify-content: center;
    flex-wrap: wrap;
    min-height: 26px;
    margin-bottom: 8px;
    padding-bottom: 7px;
    text-align: center;
    border-bottom: 1px solid var(--ld-line-soft);
}

#chat .mes .name_text {
    color: var(--ld-text-warm);
    font-family: var(--ld-font-body);
    font-size: 1.02em;
    font-weight: 400;
    letter-spacing: 0.10em;
    text-shadow: none;
}

#chat .mes[is_user="false"] .name_text {
    color: var(--ld-text-cool);
}

#chat .mes .timestamp,
#chat .mes :is(.mes_timer, .tokenCounterDisplay, .mesIDDisplay) {
    color: var(--ld-muted);
    font-family: var(--ld-font-display);
    font-size: 0.82em;
    letter-spacing: 0.06em;
    opacity: 0.86;
    text-shadow: none;
}

#chat .mes :is(.mes_buttons, .mes_edit_buttons) {
    color: var(--ld-text-cool);
}

#chat .mes :is(.mes_button, .menu_button) {
    color: var(--ld-text-cool);
    border-radius: var(--ld-radius-xs);
    background-color: transparent;
    text-shadow: none;
}

#chat .mes :is(.mes_button, .menu_button):hover,
#chat .mes :is(.mes_button, .menu_button):focus-visible {
    color: var(--ld-text-warm);
    background-color: rgba(132, 169, 184, 0.14);
    filter: none;
}

#chat .mes_reasoning_details {
    margin-block: 10px;
    color: var(--ld-ink);
    border: 1px solid var(--ld-line-soft);
    border-radius: var(--ld-radius-sm);
    background-color: rgba(8, 29, 44, 0.62);
}

#chat .mes_reasoning_summary {
    color: var(--ld-text-cool);
    background-color: rgba(31, 82, 133, 0.34);
    text-shadow: none;
}

#chat .mes_reasoning {
    color: var(--ld-pearl);
    background-color: transparent;
}

#chat .mes[is_system="true"],
#chat .smallSysMes {
    margin-block: 8px;
    color: var(--ld-pearl);
    border: 1px solid var(--ld-line-soft);
    border-radius: var(--ld-radius-sm);
    background-color: rgba(8, 29, 44, 0.76);
    box-shadow: none;
    text-shadow: none;
}

#chat :is(.swipe_left, .swipe_right, .swipes-counter) {
    color: var(--ld-text-cool);
    text-shadow: 0 0 10px rgba(132, 169, 184, 0.38);
}

/* T02 · 仅作用于聊天正文语义元素。 */

#chat .mes_text {
    box-sizing: border-box;
    width: min(100%, 72ch);
    min-width: 0;
    margin-inline: auto;
    color: var(--ld-ink);
    font-family: var(--ld-font-body);
    font-size: 1em;
    line-height: 1.86;
    letter-spacing: 0.025em;
    overflow-wrap: anywhere;
    text-shadow: none;
}

#chat .mes_text :is(p, ul, ol, blockquote, pre, table, details) {
    margin-block: 0.78em;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    color: var(--ld-text-warm);
    font-family: var(--ld-font-body);
    font-weight: 400;
    letter-spacing: 0.10em;
    line-height: 1.35;
    text-shadow: none;
}

#chat .mes_text h1 {
    padding-bottom: 0.35em;
    border-bottom: 1px solid var(--ld-line);
    font-size: 1.58em;
}

#chat .mes_text :is(em, i) {
    color: var(--ld-pearl);
}

#chat .mes_text :is(strong, b) {
    color: var(--ld-text-warm);
    font-weight: 400;
}

#chat .mes_text blockquote {
    padding: 0.65em 1em;
    color: var(--ld-pearl);
    border-left: 3px solid var(--ld-mist);
    border-radius: 0 var(--ld-radius-sm) var(--ld-radius-sm) 0;
    background-color: rgba(132, 169, 184, 0.10);
}

#chat .mes_text :is(code, pre) {
    font-family: var(--ld-font-mono);
}

#chat .mes_text code {
    padding: 0.12em 0.38em;
    color: var(--ld-text-warm);
    border: 1px solid var(--ld-line-soft);
    border-radius: 5px;
    background-color: rgba(8, 29, 44, 0.72);
}

#chat .mes_text pre {
    max-width: 100%;
    padding: 0.9em 1em;
    color: var(--ld-ink);
    border: 1px solid var(--ld-line);
    border-radius: var(--ld-radius-sm);
    background-color: rgba(8, 29, 44, 0.88);
    overflow-x: auto;
}

#chat .mes_text pre code {
    padding: 0;
    color: inherit;
    border: 0;
    background: transparent;
}

#chat .mes_text table {
    display: block;
    max-width: 100%;
    border-collapse: collapse;
    overflow-x: auto;
}

#chat .mes_text :is(th, td) {
    padding: 0.52em 0.72em;
    border: 1px solid var(--ld-line-soft);
}

#chat .mes_text th {
    color: var(--ld-text-warm);
    background-color: rgba(31, 82, 133, 0.54);
}

#chat .mes_text hr {
    height: 1px;
    margin-block: 1.5em;
    border: 0;
    background-image: linear-gradient(90deg, transparent, var(--ld-mist), var(--ld-peach), transparent);
}

#chat .mes_text a {
    color: var(--ld-text-warm);
    text-underline-offset: 0.18em;
}

#chat .mes_text img,
#chat .mes_media_wrapper img {
    max-width: 100%;
    border: 1px solid var(--ld-line);
    border-radius: var(--ld-radius-sm);
}

/* W02 · 九个入口保留原意，无九个重复底板。 */

#top-bar {
    color: var(--ld-mist);
    border-bottom: 1px solid var(--ld-line);
    border-radius: 0 0 var(--ld-radius-md) var(--ld-radius-md);
    background-color: rgba(8, 29, 44, 0.94);
    background-image: linear-gradient(90deg, transparent, rgba(132, 169, 184, 0.22), transparent);
    box-shadow: var(--ld-shadow-soft);
    text-shadow: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable) {
    color: var(--ld-mist);
    border: 0;
    border-radius: 0;
    background-color: transparent;
    box-shadow: inset 0 -2px 0 transparent;
    text-shadow: 0 0 9px rgba(132, 169, 184, 0.24);
}

#top-settings-holder .drawer-toggle {
    position: relative;
}

#top-settings-holder .drawer-toggle::after {
    content: "✦";
    position: absolute;
    top: 2px;
    right: 2px;
    color: transparent;
    font-size: 8px;
    line-height: 1;
    text-shadow: none;
    transition: color var(--ld-speed) ease, transform var(--ld-speed) ease;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable):hover {
    color: var(--ld-peach);
    background-color: rgba(31, 82, 133, 0.24);
    box-shadow: inset 0 -2px 0 var(--ld-peach);
    filter: none;
}

#top-settings-holder .drawer-toggle:hover::after,
#top-settings-holder .drawer-toggle:focus-visible::after {
    color: var(--ld-peach);
    transform: scale(1.15) rotate(16deg);
}

#top-settings-holder .openIcon,
#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable)[aria-expanded="true"] {
    color: var(--ld-peach);
    background-color: rgba(132, 169, 184, 0.16);
    box-shadow: inset 0 -3px 0 var(--ld-mist);
    filter: none;
}

#ai-config-button,
#sys-settings-button,
#advanced-formatting-button,
#WI-SP-button,
#user-settings-button,
#backgrounds-button,
#extensions-settings-button,
#persona-management-button,
#rightNavHolder {
    background-color: transparent;
}

/* W03 · 菜单、魔法棒、纸飞机与停止状态。 */

#send_form {
    position: relative;
    box-sizing: border-box;
    align-items: flex-end;
    gap: 8px;
    width: calc(100% - 24px);
    max-width: 960px;
    min-height: 66px;
    margin: 10px auto 12px;
    padding: 8px 10px;
    color: var(--ld-ink);
    border: 1px solid var(--ld-line);
    border-radius: 24px 7px 24px 7px;
    background-color: rgba(8, 29, 44, 0.96);
    background-image: linear-gradient(120deg, rgba(31, 82, 133, 0.42), transparent 45%, rgba(248, 197, 162, 0.10));
    box-shadow: inset 4px 0 0 rgba(132, 169, 184, 0.58), inset -4px 0 0 rgba(248, 197, 162, 0.34), var(--ld-shadow-soft);
    text-shadow: none;
}

#send_form::before,
#send_form::after {
    position: absolute;
    color: var(--ld-mist);
    font-family: var(--ld-font-display);
    line-height: 1;
    text-shadow: 0 0 10px currentColor;
}

#send_form::before {
    content: "✦";
    top: 6px;
    left: 8px;
    font-size: 10px;
}

#send_form::after {
    content: "✧";
    right: 9px;
    bottom: 7px;
    color: var(--ld-peach);
    font-size: 14px;
}

#send_form:focus-within {
    border-color: var(--ld-peach);
    box-shadow: inset 4px 0 0 var(--ld-mist), inset -4px 0 0 var(--ld-peach), 0 0 0 2px rgba(248, 197, 162, 0.14), var(--ld-shadow-soft);
}

#send_textarea {
    margin: 0;
    min-height: 48px;
    height: auto;
    max-height: 40dvh;
    padding: 11px 15px;
    color: var(--ld-ink);
    border: 1px solid var(--ld-line-soft);
    border-radius: 17px 5px 17px 5px;
    background-color: rgba(14, 45, 67, 0.82);
    box-shadow: inset 0 1px 0 rgba(245, 241, 234, 0.05);
    font-family: var(--ld-font-body);
    line-height: 1.72;
    text-shadow: none;
}

#send_textarea:focus {
    border-color: rgba(248, 197, 162, 0.72);
    background-color: rgba(14, 45, 67, 0.94);
}

#nonQRFormItems {
    align-items: flex-end;
    gap: 8px;
}

#leftSendForm,
#rightSendForm {
    align-items: center;
    gap: 4px;
}

#send_textarea::placeholder {
    color: var(--ld-muted);
    opacity: 0.76;
}

#leftSendForm > div,
#rightSendForm > div {
    min-width: 40px;
    min-height: 40px;
    color: var(--ld-mist);
    border: 1px solid transparent;
    border-radius: 14px 4px 14px 4px;
    background-color: rgba(31, 82, 133, 0.18);
    text-shadow: none;
}

#leftSendForm > div:hover,
#rightSendForm > div:hover {
    color: var(--ld-peach);
    border-color: var(--ld-line-soft);
    background-color: rgba(31, 82, 133, 0.46);
    filter: none;
}

#options_button,
#extensionsMenuButton,
#send_but {
    position: relative;
}

#options_button::after,
#extensionsMenuButton::after,
#send_but::after {
    content: "✦";
    position: absolute;
    top: 1px;
    right: 1px;
    color: var(--ld-peach);
    font-size: 8px;
    line-height: 1;
    text-shadow: 0 0 8px currentColor;
}

#send_but.fa-paper-plane {
    color: var(--ld-peach);
    background-color: transparent;
    transition: color var(--ld-speed) ease, transform var(--ld-speed) ease;
}

#send_but.fa-paper-plane:hover {
    color: var(--ld-navy);
    background-color: var(--ld-peach);
    transform: rotate(-8deg) scale(1.04);
}

#send_form .mes_stop,
#mes_stop {
    color: var(--ld-navy);
    background-color: var(--ld-peach);
}

#options,
#extensionsMenu {
    color: var(--ld-ink);
    border: 1px solid var(--ld-line);
    border-radius: var(--ld-radius-wing);
    background-color: rgba(8, 29, 44, 0.98);
    box-shadow: var(--ld-shadow);
    text-shadow: none;
}

/* 共享令牌只处理明确列出的核心窗口内部控件。 */

:is(
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel
) {
    color: var(--ld-ink);
    border-color: var(--ld-line);
    background-color: var(--ld-panel);
    background-image: linear-gradient(90deg, var(--ld-mist), var(--ld-blue), var(--ld-peach));
    background-position: top;
    background-repeat: no-repeat;
    background-size: 100% 3px;
    box-shadow: var(--ld-shadow);
    text-shadow: none;
}

:is(
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup,
    #options,
    #extensionsMenu
) :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), textarea, select, .select2-selection) {
    color: var(--ld-ink);
    border-color: var(--ld-line-soft);
    border-radius: var(--ld-radius-xs);
    background-color: rgba(8, 29, 44, 0.84);
    font-family: var(--ld-font-body);
    box-shadow: inset 3px 0 0 rgba(132, 169, 184, 0.38);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

:is(
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup
) :is(select option, select optgroup) {
